// The internal contract we control
public interface IPdfGenerator
{
    Task<byte[]> GenerateAsync(Invoice invoice, CancellationToken ct = default);
}

// Implementation using a third-party library
// If we switch libraries later, only this class changes.
public class IronPdfGenerator : IPdfGenerator
{
    public async Task<byte[]> GenerateAsync(Invoice invoice, CancellationToken ct = default)
    {
        // Third-party library implementation
        var renderer = new ChromePdfRenderer();
        var html = RenderInvoiceToHtml(invoice);
        var doc = await renderer.RenderHtmlAsPdfAsync(html, ct);
        return doc.Stream.ToArray();
    }

    private string RenderInvoiceToHtml(Invoice invoice)
    {
        // Could be Razor, Scriban, or any templating engine
        return TemplateEngine.Render("InvoiceTemplate", invoice);
    }
}

// Consumption code never depends on the library
public class InvoiceService
{
    private readonly IPdfGenerator _pdfGenerator;

    public InvoiceService(IPdfGenerator pdfGenerator)
    {
        _pdfGenerator = pdfGenerator;
    }

    public async Task<byte[]> GetInvoicePdfAsync(Guid invoiceId)
    {
        var invoice = await _invoiceRepository.GetByIdAsync(invoiceId);
        return await _pdfGenerator.GenerateAsync(invoice);
    }
}
